          if (!item.changePerson) {
            msgs = msgs + '更换原因不能为空，';
          }
        }
        if (!item.userName || !item.userName || !item.userName) {
          msgs = msgs + '使用人信息不能为空，';
        }
      });
      if (msgs) {
        this.$message({
          type: "warning",
          message: "请检查投运设备列表," + msgs
        });
        return true;
      }
      return false;
    }
  }
};
